raw:
npm i -g release-it@${RELEASE_IT_VERSION}
npm i -g @release-it/bumper@${BUMPER_VERSION}
release-it -- ${UPDATE_ARGS} --ci

inputs.branches:
[
  '+([0-9])?(.{+([0-9]),x}).x',
  'main',
  'next',
  'next-major',
  {
    name: 'beta',
    prerelease: true
  },
  {
    name: 'alpha',
    prerelease: true
  }
]

raw:
$vswhere = Join-Path ${env:ProgramFiles(x86)} "Microsoft Visual Studio\Installer\vswhere.exe"
if (!(Test-Path $vswhere)) {
  throw "vswhere.exe not found"
}

$vcvars = & $vswhere -latest -products * -requires Microsoft.VisualStudio.Component.VC.Tools.ARM64 -find "VC\Auxiliary\Build\vcvarsall.bat" | Select-Object -First 1
if (!$vcvars) {
  throw "Visual Studio ARM64 build tools not found"
}

& $env:ComSpec /c "call `"$vcvars`" x64_arm64 >nul && set CC_aarch64_pc_windows_msvc=cl.exe && dist build ${{ needs.plan.outputs.tag-flag }} --print=linkage --output-format=json ${{ matrix.dist_args }} > dist-manifest.json"
if ($LASTEXITCODE -ne 0) {
  exit $LASTEXITCODE
}
echo "dist ran successfully"
